const WORKSPACE_PANEL_PADDING = 3

function openDocumentPath(document: OpenDocument) {
    return document.kind === 'card' ? document.getObject().path : document.getObject().sourcePath
}

function flushPendingCommits() {
    flushMarkdownEditors()
    void projectPersistenceService.flushPendingChanges().catch((error: unknown) => {
        dialogService.error(error, { fallbackMessage: 'Pending changes could not be saved' })
    })
}

async function flushAndConfirmPendingCommits(lifecycleBridge: ElectronLifecycleBridge, requestId: string) {
    try {
        flushMarkdownEditors()
        await projectPersistenceService.flushPendingChanges()
        lifecycleBridge.confirmFlush(requestId)
    } catch (error) {
        dialogService.error(error, { fallbackMessage: 'Pending changes could not be saved before closing' })
    }
}

function runWorkspaceEdit(action: () => void, fallbackMessage: string) {
    try {
        action()
    } catch (error) {
        dialogService.error(error, { fallbackMessage })
    }
}

interface ProjectWorkspaceProps {
    auth: UseGithubAuthResult
    isMenuOpen: boolean
    onLeftPanelInteraction: () => void
}

export function ProjectWorkspace(props: ProjectWorkspaceProps) {
    const { auth, isMenuOpen, onLeftPanelInteraction } = props
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
    const project = useProjectReference()
    const projectConfig = useProjectConfig()
    const workingFolder = useWorkingFolder()
    const cardTypes = projectConfig?.cardTypes ?? DEFAULT_CARD_TYPES
    const states = projectConfig?.states ?? DEFAULT_STATES
    const projectFolder = projectConfig?.projectFolder ?? DEFAULT_PROJECT_FOLDER
    const actionsFolder = projectConfig?.actionsFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_ACTIONS_FOLDER}`
    const archivedFolder = projectConfig?.archivedFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_ARCHIVED_FOLDER}`
    const releasesFolder = projectConfig?.releasesFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_RELEASES_FOLDER}`
    const mobileScrollContainerRef = useRef<HTMLDivElement>(null)
    const onLeftPanelInteractionRef = useRef(onLeftPanelInteraction)
    const statusColors = useMemo(() => new Map(
        states.map(({ color, state }, index) => [state, color ?? defaultColumnAccent(index)]),
    ), [states])

    useEffect(() => {
        onLeftPanelInteractionRef.current = onLeftPanelInteraction
    })

    const handleCreateFolder = useCallback(async (parentDirectory: string, name: string) => {
        await dataService.cards.createFolder(parentDirectory, name)
    }, [])

    const handleCreateMarkdownFile = useCallback(async (parentDirectory: string, name: string) => {
        await dataService.cards.createMarkdownFile(parentDirectory, name)
    }, [])

    const handleDeleteFile = useCallback(async (path: string) => {
        try {
            await dataService.cards.deleteFile(path)
            const document = openFilesService.getSnapshot().documents.find((candidate) => openDocumentPath(candidate) === path)
            if (document) openFilesService.closeDocument(document)
            workspaceViewService.clearSelectedPath(path)
            onLeftPanelInteractionRef.current()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: `File delete failed: ${path}` })
            throw error
        }
    }, [])

    const handleDeleteFolder = useCallback(async (path: string) => {
        try {
            await dataService.cards.deleteFolder(path)
            const folderPrefix = `${path.replace(/\/+$/u, '')}/`
            const documents = openFilesService.getSnapshot().documents
            for (const document of documents) {
                const openPath = openDocumentPath(document)
                if (openPath?.startsWith(folderPrefix)) openFilesService.closeDocument(document)
            }
            const selectedPath = workspaceViewService.getSnapshot().selectedPath
            if (selectedPath?.startsWith(folderPrefix)) workspaceViewService.clearSelectedPath(selectedPath)
            onLeftPanelInteractionRef.current()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: `Folder deletion failed: ${path}` })
            throw error
        }
    }, [])

    useEffect(() => {
        const handleBeforeUnload = (event: BeforeUnloadEvent) => {
            flushMarkdownEditors()
            const { hasPendingPush, hasPendingSave } = projectPersistenceService.getSnapshot()
            // In Electron, vetoing beforeunload silently cancels the window close (no confirm
            // dialog), leaving the app unclosable. The main process flushes pending commits on
            // quit instead, so only prompt in a plain browser build.
            if ((hasPendingPush || hasPendingSave) && !getElectronLifecycleBridge()) {
                event.preventDefault()
                event.returnValue = ''
            }

            flushPendingCommits()
        }

        const handleVisibilityChange = () => {
            if (document.visibilityState === 'hidden') flushPendingCommits()
        }

        const handleBlur = () => {
            flushMarkdownEditors()
            if (projectPersistenceService.getSnapshot().hasPendingSave) flushPendingCommits()
        }

        document.addEventListener('visibilitychange', handleVisibilityChange)
        window.addEventListener('beforeunload', handleBeforeUnload)
        window.addEventListener('blur', handleBlur)

        return () => {
            document.removeEventListener('visibilitychange', handleVisibilityChange)
            window.removeEventListener('beforeunload', handleBeforeUnload)
            window.removeEventListener('blur', handleBlur)
        }
    }, [])

    useEffect(() => {
        const lifecycleBridge = getElectronLifecycleBridge()
        if (!lifecycleBridge) return undefined

        return lifecycleBridge.onFlushRequested((requestId) => {
            void flushAndConfirmPendingCommits(lifecycleBridge, requestId)
        })
    }, [])

    useEffect(() => {
        const handleNavigationOpen = (event: Event) => {
            const { path } = (event as CustomEvent<WorkspaceOpenRequest>).detail
            // Reveal the card/file without changing the current view mode: highlight it in card view
            // and open it in the service-owned text-view tabs.
            workspaceViewService.selectPath(path)
            runWorkspaceEdit(() => openFilesService.openPath(path), `File open failed: ${path}`)
            telemetryService.trackEvent('navigation')
        }

        workspaceNavigationService.addEventListener('open', handleNavigationOpen)

        return () => workspaceNavigationService.removeEventListener('open', handleNavigationOpen)
    }, [])

    const fileTree = (
        <Box
            aria-label="File tree"
            sx={{ bgcolor: 'action.hover', display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0 }}
        >
            <FileTreeView
                actionsFolder={actionsFolder}
                archivedFolder={archivedFolder}
                cardTypes={cardTypes}
                onCreateFolder={handleCreateFolder}
                onCreateMarkdownFile={handleCreateMarkdownFile}
                onDeleteFile={handleDeleteFile}
                onDeleteFolder={handleDeleteFolder}
                onLeftPanelInteraction={onLeftPanelInteraction}
                projectFolder={projectFolder}
                releasesFolder={releasesFolder}
                statusColors={statusColors}
                workingFolder={workingFolder}
            />
        </Box>
    )
    const textView = (
        <Paper
            elevation={0}
            sx={{
                border: 1,
                borderColor: 'divider',
                borderRadius: 2,
                boxSizing: 'border-box',
                display: 'flex',
                height: '100%',
                minHeight: 0,
                overflow: 'hidden',
                p: WORKSPACE_PANEL_PADDING,
            }}
        >
            <TextView
                actionsFolder={actionsFolder}
                archivedFolder={archivedFolder}
                cardTypes={cardTypes}
                projectFolder={projectFolder}
                releasesFolder={releasesFolder}
                states={states}
            />
        </Paper>
    )

    const workspace = (
        <ProjectWorkspaceAvailability>
            {isMobile ? (
                <MobileCardView cardTypes={cardTypes} states={states} statusColors={statusColors} />
            ) : (
                <CardView cardTypes={cardTypes} states={states} statusColors={statusColors} />
            )}
			<CardActionPopupHost />
        </ProjectWorkspaceAvailability>
    )
    const navigation = project ? fileTree : (
        <Box sx={{ p: 2 }}>
            <Typography color="text.secondary" variant="body2">
                No project navigation available.
            </Typography>
        </Box>
    )

    return (
        <Box
            aria-label="Project workspace"
            component="section"
            sx={{ display: 'flex', flex: 1, minHeight: 0, overflow: isMobile ? 'unset' : 'hidden' }}
        >
            {isMobile ? (
                <MobileMainWindow
                    auth={auth}
                    cardNavigation={project ? <MobileCardViewMenu onSelected={onLeftPanelInteraction} states={states} /> : null}
                    isMenuOpen={isMenuOpen}
                    leftPanel={navigation}
                    onCloseMenu={onLeftPanelInteraction}
                    rightPanel={workspace}
                    rightPanelContainerRef={mobileScrollContainerRef}
                    showNavigationInCards={!project}
                />
            ) : workspace}
        </Box>
    )
}
import { Box, useMediaQuery, useTheme } from '@mui/material'
import { useCallback, useMemo, useState, type ReactNode } from 'react'
import { navigateTo, useAppLocation } from '../../app/app_navigation'
import type { UseGithubAuthResult } from '../../auth/use_github_auth'
import { ConfigPage } from '../config/config_page'
import { useProjectReference } from '../hooks/use_project_reference'
import { ProjectWorkspace } from '../project_workspace'
import { createSearchRegexpAgent, isSearchRegexpAgentAvailable } from '../../services/search/search_regexp_agent'
import { AppMenu } from './menu/app_menu'
import { SearchControl } from './search/search_control'
import { StatusBar } from './status_bar'

interface MainWindowProps {
    auth: UseGithubAuthResult
    toolbarAction: ReactNode
}

/** Main window: owns the global layout and switches between desktop and mobile presentations. */
export function MainWindow(props: MainWindowProps) {
    const { auth, toolbarAction } = props
    const location = useAppLocation()
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
    const [isMenuOpen, setIsMenuOpen] = useState(false)
    const project = useProjectReference()
    const isConfigOpen = location.pathname === '/config'
    const regexpAgent = useMemo(
        () => isSearchRegexpAgentAvailable() ? createSearchRegexpAgent() : undefined,
        [],
    )

    const handleOpenMenu = useCallback(() => {
        setIsMenuOpen(true)
    }, [])

    const handleCloseMenu = useCallback(() => {
        setIsMenuOpen(false)
    }, [])

    const handleOpenConfig = useCallback(() => {
        navigateTo('/config')
    }, [])

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
            <AppMenu
                accessToken={auth.accessToken}
                auth={auth}
                extraActions={toolbarAction}
                isGithubAuthenticated={auth.isAuthenticated}
                isMobile={isMobile}
                onOpenConfig={handleOpenConfig}
                onOpenMobileMenu={handleOpenMenu}
                search={<SearchControl isMobile={isMobile} regexpAgent={regexpAgent} />}
            />
            <ProjectWorkspace
                auth={auth}
                isMenuOpen={isMenuOpen}
                key={project ? `${project.id}:${project.branch}` : 'no-project'}
                onLeftPanelInteraction={handleCloseMenu}
            />
            {!isMobile ? <StatusBar /> : null}
            {isConfigOpen ? <ConfigPage hash={location.hash} /> : null}
        </Box>
    )
}
import { Box } from '@mui/material'
import { useEffect, useMemo, useRef } from 'react'
import {
    DEFAULT_ARCHIVED_FOLDER,
    DEFAULT_RELEASES_FOLDER,
    defaultColumnAccent,
    type CardTypeConfig,
    type StateConfig,
} from '../../data/data_types'
import { dialogService } from '../../services/dialog_service'
import { workspaceViewService } from '../../services/project/workspace_view_service'
import { useWorkingFolder } from '../hooks/use_working_folder'
import { TextEditorPane } from './text_editor_pane'

interface TextViewProps {
    actionsFolder: string
    archivedFolder?: string
    cardTypes: CardTypeConfig[]
    projectFolder: string
    releasesFolder?: string
    states: StateConfig[]
}

function folderPath(parentFolder: string, childFolder: string) {
    return parentFolder.length > 0 ? `${parentFolder}/${childFolder}` : childFolder
}

function folderName(path: string): string | null {
    const name = path.replace(/\\/gu, '/').split('/').filter((part) => part.length > 0).at(-1)

    return name ?? null
}

/** Lifetime-stable text editor surface, hidden directly when card view is active. */
export function TextView(props: TextViewProps) {
    const {
        actionsFolder,
        archivedFolder = folderPath(props.projectFolder, DEFAULT_ARCHIVED_FOLDER),
        cardTypes,
        releasesFolder = folderPath(props.projectFolder, DEFAULT_RELEASES_FOLDER),
        states,
    } = props
    const workingFolder = useWorkingFolder()
    const rootElementRef = useRef<HTMLDivElement>(null)
    const missingRootReportedRef = useRef(false)
    const specialFolderPaths = useMemo(
        () => [actionsFolder, workingFolder, releasesFolder, archivedFolder],
        [actionsFolder, archivedFolder, releasesFolder, workingFolder],
    )
    const specialContextTypes = useMemo(
        () => specialFolderPaths.map(folderName).filter((name): name is string => name !== null),
        [specialFolderPaths],
    )
    const invalidFolderPath = specialFolderPaths.find((path) => folderName(path) === null) ?? null
    const actionStates = useMemo(() => states.map(({ state }) => state), [states])
    const statusColors = useMemo(() => new Map(
        states.map(({ color, state }, index) => [state, color ?? defaultColumnAccent(index)]),
    ), [states])

    useEffect(() => {
        if (invalidFolderPath !== null) {
            dialogService.error(`Cannot derive context type from folder path: ${invalidFolderPath}`)
        }
    }, [invalidFolderPath])

    useEffect(() => {
        const updateVisibility = () => {
            const rootElement = rootElementRef.current
            if (!rootElement) {
                if (!missingRootReportedRef.current) {
                    missingRootReportedRef.current = true
                    dialogService.error(new Error('Missing text view root element'), {fallbackMessage: 'Text view could not be displayed'})
                }
                return
            }

            rootElement.style.display = workspaceViewService.getSnapshot().viewMode === 'text' ? 'flex' : 'none'
        }

        updateVisibility()
        workspaceViewService.addEventListener('changed', updateVisibility)

        return () => workspaceViewService.removeEventListener('changed', updateVisibility)
    }, [])

    return (
        <Box ref={rootElementRef} sx={{ display: 'flex', flex: 1, minHeight: 0 }}>
            <TextEditorPane
                actionsFolder={actionsFolder}
                cardTypes={cardTypes}
                specialContextTypes={specialContextTypes}
                states={actionStates}
                statusColors={statusColors}
            />
        </Box>
    )
}
import { Box } from '@mui/material'
import { DndContext, DragOverlay, PointerSensor, closestCorners, useSensor, useSensors } from '@dnd-kit/core'
import type { DragEndEvent, DragMoveEvent, DragStartEvent } from '@dnd-kit/core'
import { useCallback, useEffect, useRef, useState } from 'react'
import type { RefObject } from 'react'
import { flushSync } from 'react-dom'
import { buildCardColumns } from '../../data/card_ordering'
import type { CardTypeConfig, StateConfig } from '../../data/data_types'
import { dataService } from '../../services/data/data_service'
import { dialogService } from '../../services/dialog_service'
import { openFilesService } from '../../services/open_files_service'
import { workspaceViewService } from '../../services/project/workspace_view_service'
import { telemetryService } from '../../services/telemetry/telemetry_service'
import { AffectsEditorDialog } from './affects_editor_dialog'
import { CardBodyPopover } from './card_body_popover'
import { cardBodyPopoverService } from './card_body_popover_service'
import { CardColumn } from './card_column'
import { CardDragOverlay } from './card_drag_overlay'
import { cardDragDropService } from './card_drag_drop_service'
import { resolveCardDragEvent } from './card_drag'
import { useCardViewColumns } from './use_card_view_columns'

const DRAG_ACTIVATION_DISTANCE = 2
interface CardViewProps {
    cardTypes: CardTypeConfig[]
    states: StateConfig[]
    statusColors: Map<string, string>
}

async function runCardEdit(action: () => unknown, fallbackMessage: string) {
    try {
        await action()
    } catch (error) {
        dialogService.error(error, { fallbackMessage })
    }
}

function currentCardColumns(states: StateConfig[]) {
    const cards = dataService.getState().snapshot?.activeCards ?? []

    return buildCardColumns(cards, states)
}

/** Card view: status columns of draggable cards with card-anchored body popup access. */
export function CardView(props: CardViewProps) {
    const {
        cardTypes,
        states,
        statusColors,
    } = props
    const columns = useCardViewColumns(states)
    const [openAffectsPath, setOpenAffectsPath] = useState<string | null>(null)
    const rootElementRef = useRef<HTMLDivElement>(null)
    const missingRootReportedRef = useRef(false)
    const wasVisibleRef = useRef<boolean | null>(null)
    const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: DRAG_ACTIVATION_DISTANCE } }))

    const handleOpenAffects = (path: string) => {
        setOpenAffectsPath(path)
    }

    const handleCloseAffects = () => {
        setOpenAffectsPath(null)
    }

    const clearActiveCard = useCallback(() => {
        cardDragDropService.endDrag()
    }, [])

    useEffect(() => {
        const updateVisibility = () => {
            const rootElement = rootElementRef.current
            if (!rootElement) {
                if (!missingRootReportedRef.current) {
                    missingRootReportedRef.current = true
                    dialogService.error(new Error('Missing card view root element'), {fallbackMessage: 'Card view could not be displayed'})
                }
                return
            }

            const isVisible = workspaceViewService.getSnapshot().viewMode === 'cards'
            rootElement.style.display = isVisible ? 'flex' : 'none'
            if (wasVisibleRef.current === isVisible) return

            wasVisibleRef.current = isVisible
            if (isVisible) return

            queueMicrotask(() => {
                cardBodyPopoverService.close()
                setOpenAffectsPath((currentPath) => currentPath === null ? currentPath : null)
                clearActiveCard()
            })
        }

        updateVisibility()
        workspaceViewService.addEventListener('changed', updateVisibility)

        return () => workspaceViewService.removeEventListener('changed', updateVisibility)
    }, [clearActiveCard])

    useEffect(() => () => cardBodyPopoverService.close(), [])

    const handleDragStart = useCallback((event: DragStartEvent) => {
        cardDragDropService.startDrag(
            String(event.active.id),
            event.active.rect.current.initial?.height ?? null,
            event.active.rect.current.initial?.width ?? null,
        )
    }, [])

    const handleDragMove = useCallback((event: DragMoveEvent) => {
        const { active, over } = event
        if (!over) {
            cardDragDropService.setDropPreview(null)
            return
        }

        const dragColumns = currentCardColumns(states)
        const drop = resolveCardDragEvent(dragColumns, event)
        const sourceColumn = dragColumns.find((column) => column.cards.some((card) => card.path === String(active.id)))
        const dropPreview = drop && sourceColumn?.status !== drop.targetStatus ? drop : null
        cardDragDropService.setDropPreview(dropPreview)
    }, [states])

    const handleDragEnd = useCallback((event: DragEndEvent) => {
        const { active, over } = event
        const drop = over ? resolveCardDragEvent(currentCardColumns(states), event) : null
        const path = String(active.id)
        if (!drop) {
            clearActiveCard()
            return
        }

        flushSync(() => {
            void runCardEdit(() => dataService.cards.moveCard(path, drop.targetStatus, drop.targetIndex), `Card move failed: ${path}`)
            clearActiveCard()
        })
    }, [clearActiveCard, states])

    const handleOpenInFileMode = (path: string) => {
        cardBodyPopoverService.close()
        workspaceViewService.selectPath(path)
        void runCardEdit(() => openFilesService.openPath(path), `File open failed: ${path}`)
        workspaceViewService.setViewMode('text')
        telemetryService.trackEvent('navigation')
    }

    const handleDeleteCard = async (path: string) => {
        try {
            await dataService.cards.deleteCard(path)
            workspaceViewService.clearSelectedPath(path)
            cardBodyPopoverService.closePath(path)
            if (openAffectsPath === path) handleCloseAffects()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: `Card delete failed: ${path}` })
            throw error
        }
    }

    const handleTitleChange = (path: string, title: string) => {
        dataService.cards.updateCardTitle(path, title).catch((error: unknown) => {
            dialogService.error(error, { fallbackMessage: `Title update failed: ${path}` })
        })
    }

    const handleTogglePolicy = (path: string, policyKey: string) => {
        void runCardEdit(() => dataService.cards.toggleCardPolicy(path, policyKey), `Policy toggle failed: ${path}`)
    }

    const handleAffectsChange = (path: string, affects: string[]) => {
        void runCardEdit(() => dataService.cards.updateCardAffects(path, affects), `Affects update failed: ${path}`)
    }

    return (
        <Box
            ref={rootElementRef}
            sx={{ bgcolor: 'background.default', display: 'flex', flex: 1, minHeight: 0, overflow: 'hidden', position: 'relative' }}
        >
            <DndContext
                collisionDetection={closestCorners}
                onDragCancel={clearActiveCard}
                onDragEnd={handleDragEnd}
                onDragMove={handleDragMove}
                onDragStart={handleDragStart}
                sensors={sensors}
            >
                <Box
                    aria-label="Card columns"
                    sx={{
                        alignItems: 'flex-start',
                        display: 'flex',
                        flex: 1,
                        flexDirection: 'row',
                        gap: 2,
                        height: '100%',
                        overflowX: 'auto',
                        overflowY: 'auto',
                        p: 2.5,
                    }}
                >
                    {columns.map((column) => (
                        <CardColumn
                            key={column.status}
                            cardTypes={cardTypes}
                            column={column}
                            isMobile={false}
                            onDeleteCard={handleDeleteCard}
                            onOpenInFileMode={handleOpenInFileMode}
                            onTitleChange={handleTitleChange}
                            onTogglePolicy={handleTogglePolicy}
                        />
                    ))}
                </Box>
                <DragOverlay>
                    <CardDragOverlay cardTypes={cardTypes} />
                </DragOverlay>
                <CardBodyPopover
                    cardTypes={cardTypes}
                    isMobile={false}
                    onDeleteCard={handleDeleteCard}
                    onOpenAffects={handleOpenAffects}
                    onOpenInFileMode={handleOpenInFileMode}
                    statusColors={statusColors}
                    visible
                />
                <AffectsEditorDialog
                    cardPath={openAffectsPath}
                    onClose={handleCloseAffects}
                    onSave={handleAffectsChange}
                />
            </DndContext>
        </Box>
    )
}
import { Box } from '@mui/material'
import type { KeyboardEvent as ReactKeyboardEvent, PointerEvent as ReactPointerEvent, ReactNode } from 'react'
import { useCallback, useEffect, useRef, useState } from 'react'
import { dialogService } from '../../services/dialog_service'
import { workspaceViewService } from '../../services/project/workspace_view_service'

export const SPLIT_WIDTH_STORAGE_KEY = 'md2.splitWidth'
const MIN_LEFT_WIDTH = 160
const MAX_LEFT_WIDTH_RATIO = 0.8
const DEFAULT_LEFT_WIDTH = 280
const SEPARATOR_WIDTH = 6
const KEYBOARD_RESIZE_STEP = 24

interface SplitLayoutProps {
    left: ReactNode
    right: ReactNode
}

function readStoredWidth(): number {
    const storedValue = window.localStorage.getItem(SPLIT_WIDTH_STORAGE_KEY)
    const parsedValue = storedValue ? Number.parseInt(storedValue, 10) : Number.NaN
    return Number.isNaN(parsedValue) ? DEFAULT_LEFT_WIDTH : parsedValue
}

function clampWidth(proposedWidth: number, containerWidth: number): number {
    const maxWidth = Math.max(MIN_LEFT_WIDTH, containerWidth * MAX_LEFT_WIDTH_RATIO)
    return Math.min(Math.max(proposedWidth, MIN_LEFT_WIDTH), maxWidth)
}

function maxWidth(containerWidth: number): number {
    return Math.max(MIN_LEFT_WIDTH, containerWidth * MAX_LEFT_WIDTH_RATIO)
}

/** Desktop body layout: a left and right panel separated by a draggable splitter. */
export function SplitLayout(props: SplitLayoutProps) {
    const { left, right } = props
    const hasLeftPanel = left !== null
    const containerRef = useRef<HTMLDivElement>(null)
    const missingContainerReportedRef = useRef(false)
    const [leftWidth, setLeftWidth] = useState(readStoredWidth)
    const [isDragging, setIsDragging] = useState(false)
    const [separatorMaxWidth, setSeparatorMaxWidth] = useState<number | undefined>(undefined)

    useEffect(() => {
        const updateVisibility = () => {
            const container = containerRef.current
            if (!container) {
                if (!missingContainerReportedRef.current) {
                    missingContainerReportedRef.current = true
                    dialogService.error(new Error('Missing split layout container'), {fallbackMessage: 'Split layout could not be displayed'})
                }
                return
            }

            container.style.display = workspaceViewService.getSnapshot().viewMode === 'text' ? 'flex' : 'none'
        }

        updateVisibility()
        workspaceViewService.addEventListener('changed', updateVisibility)

        return () => workspaceViewService.removeEventListener('changed', updateVisibility)
    }, [])

    const handlePointerDown = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
        event.preventDefault()
        if (containerRef.current) setSeparatorMaxWidth(maxWidth(containerRef.current.getBoundingClientRect().width))
        setIsDragging(true)
        event.currentTarget.setPointerCapture?.(event.pointerId)
    }, [])

    const handlePointerMove = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
        if (!isDragging || !containerRef.current) return

        const bounds = containerRef.current.getBoundingClientRect()
        setSeparatorMaxWidth(maxWidth(bounds.width))
        setLeftWidth(clampWidth(event.clientX - bounds.left, bounds.width))
    }, [isDragging])

    const handlePointerUp = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
        if (!isDragging) return

        setIsDragging(false)
        event.currentTarget.releasePointerCapture?.(event.pointerId)
        setLeftWidth((currentWidth) => {
            window.localStorage.setItem(SPLIT_WIDTH_STORAGE_KEY, String(Math.round(currentWidth)))
            return currentWidth
        })
    }, [isDragging])

    const handleSeparatorKeyDown = useCallback((event: ReactKeyboardEvent<HTMLDivElement>) => {
        if (!containerRef.current) return

        const bounds = containerRef.current.getBoundingClientRect()
        setSeparatorMaxWidth(maxWidth(bounds.width))
        const nextWidthByKey: Record<string, number> = {
            ArrowLeft: leftWidth - KEYBOARD_RESIZE_STEP,
            ArrowRight: leftWidth + KEYBOARD_RESIZE_STEP,
            End: maxWidth(bounds.width),
            Home: MIN_LEFT_WIDTH,
        }
        const nextWidth = nextWidthByKey[event.key]
        if (nextWidth === undefined) return

        event.preventDefault()
        const clampedWidth = clampWidth(nextWidth, bounds.width)
        setLeftWidth(clampedWidth)
        window.localStorage.setItem(SPLIT_WIDTH_STORAGE_KEY, String(Math.round(clampedWidth)))
    }, [leftWidth])

    return (
        <Box ref={containerRef} sx={{ display: 'flex', flex: 1, minHeight: 0, overflow: 'hidden' }}>
            <Box hidden={!hasLeftPanel} sx={{ flexShrink: 0, minWidth: 0, overflow: 'auto', width: leftWidth }}>
                {left}
            </Box>
            <Box
                aria-label="Resize panels"
                aria-orientation="vertical"
                aria-valuemax={separatorMaxWidth}
                aria-valuemin={MIN_LEFT_WIDTH}
                aria-valuenow={Math.round(leftWidth)}
                onKeyDown={handleSeparatorKeyDown}
                onPointerDown={handlePointerDown}
                onPointerMove={handlePointerMove}
                onPointerUp={handlePointerUp}
                role="separator"
                hidden={!hasLeftPanel}
                sx={{
                    bgcolor: isDragging ? 'primary.main' : 'divider',
                    cursor: 'col-resize',
                    flexShrink: 0,
                    width: SEPARATOR_WIDTH,
                    '&:hover': { bgcolor: 'primary.main' },
                }}
                tabIndex={hasLeftPanel ? 0 : -1}
            />
            <Box sx={{ flex: 1, minWidth: 0, overflow: 'auto' }}>
                {right}
            </Box>
        </Box>
    )
}
import { Box, Divider, Drawer, Typography } from '@mui/material'
import type { ReactNode, RefObject } from 'react'
import { useCallback, useEffect, useRef } from 'react'
import type { UseGithubAuthResult } from '../../auth/use_github_auth'
import { workspaceViewService } from '../../services/project/workspace_view_service'
import { GithubAuthToolbarButton } from './github_auth_toolbar_button'
import { ThemeModeToggle } from './menu/theme_mode_toggle'

const MOBILE_DRAWER_WIDTH = 300

interface MobileMainWindowProps {
    auth: UseGithubAuthResult
    cardNavigation: ReactNode | null
    isMenuOpen: boolean
    leftPanel: ReactNode
    onCloseMenu: () => void
    rightPanel: ReactNode
    rightPanelContainerRef: RefObject<HTMLDivElement | null>
    showNavigationInCards: boolean
}

/** Mobile window layout with navigation drawer and workspace content. */
export function MobileMainWindow(props: MobileMainWindowProps) {
    const { auth, cardNavigation, isMenuOpen, leftPanel, onCloseMenu } = props
    const { rightPanel, rightPanelContainerRef, showNavigationInCards } = props
    const cardNavigationElementRef = useRef<HTMLDivElement>(null)
    const navigationElementRef = useRef<HTMLDivElement>(null)
    const updateDrawerVisibility = useCallback(() => {
        const isTextView = workspaceViewService.getSnapshot().viewMode === 'text'
        if (navigationElementRef.current) {
            navigationElementRef.current.style.display = isTextView || showNavigationInCards ? 'flex' : 'none'
        }
        if (cardNavigationElementRef.current) {
            cardNavigationElementRef.current.style.display = !isTextView && !showNavigationInCards ? 'block' : 'none'
        }
    }, [showNavigationInCards])
    const handleNavigationElement = useCallback((element: HTMLDivElement | null) => {
        navigationElementRef.current = element
        updateDrawerVisibility()
    }, [updateDrawerVisibility])
    const handleCardNavigationElement = useCallback((element: HTMLDivElement | null) => {
        cardNavigationElementRef.current = element
        updateDrawerVisibility()
    }, [updateDrawerVisibility])

    useEffect(() => {
        updateDrawerVisibility()
        workspaceViewService.addEventListener('changed', updateDrawerVisibility)

        return () => workspaceViewService.removeEventListener('changed', updateDrawerVisibility)
    }, [updateDrawerVisibility])

    return (
        <>
            <Drawer onClose={onCloseMenu} open={isMenuOpen}>
                <Box sx={{ display: 'flex', flexDirection: 'column', height: '100%', width: MOBILE_DRAWER_WIDTH }}>
                    <Box sx={{ alignItems: 'center', display: 'flex', justifyContent: 'space-between', p: 1.5 }}>
                        <Typography sx={{ fontWeight: 600 }} variant="body2">Theme</Typography>
                        <ThemeModeToggle />
                    </Box>
                    <Box sx={{ flex: 1, minHeight: 0 }}>
                        <Box ref={handleCardNavigationElement}>{cardNavigation}</Box>
                        <Box ref={handleNavigationElement} sx={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
                            <Divider />
                            <Box sx={{ flex: 1, minHeight: 0, overflow: 'auto' }}>{leftPanel}</Box>
                        </Box>
                    </Box>
                    <Divider />
                    <Box component="footer" sx={{ display: 'flex', justifyContent: 'flex-end', p: 1.5 }}>
                        <GithubAuthToolbarButton auth={auth} />
                    </Box>
                </Box>
            </Drawer>
            <Box ref={rightPanelContainerRef} sx={{ flex: 1, minHeight: 0, overflow: 'auto' }}>{rightPanel}</Box>
        </>
    )
}

